import React, { useEffect, useState } from "react";
import { makeApiRequest } from "../axiosService/ApiCall";
import { toast, ToastContainer } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import { Button, Modal } from "react-bootstrap";
import { MdOutlineRemoveRedEye } from "react-icons/md";
import axios from "axios";

function Sitesetting() {
  const [loading, setLoading] = useState(false);
  const [previewOpen, setPreviewOpen] = useState(false);

  // Separate form states
  const [copyrightData, setCopyrightData] = useState({ copyright: "" });
  const [socialData, setSocialData] = useState({ socialLink: "" });
  const [coinFeeData, setCoinFeeData] = useState({
    BTCUSDT: "",
    ETHUSDT: "",
    SOLUSDT: "",
    ADAUSDT: "",
    LTCUSDT: "",
    USDT: "",
  });

  // Separate errors

  const [previewImage, setPreviewImage] = useState(null);
  const [imageFile, setImageFile] = useState(null);
  const [emailContent, setEmailContent] = useState("");
  const [expireTime, setExpireTime] = useState("");
  const [copyright, setCopyright] = useState("");
  const [isImageValid, setIsImageValid] = useState(true);
  const [emailSubject, setEmailSubject] = useState("");
  const [resendOTPexpireTime, setResendOTPExpireTime] = useState("");
  const [siteSettingEdit, setSiteSettingEdit] = useState(0);
  const [adminType, setAdminType] = useState("");
  const [logoPosition, setLogoPosition] = useState("center");
  // const [lastLine, setLastLine] = useState("");

  const SitesettingRes = async () => {
    try {
      let params = {
        url: "view-edit-GetData",
        method: "GET",
        headers: {
          Authorization: `Bearer ${localStorage.getItem("token")}`,
        },
      };
      const siteSettingEditRes = await makeApiRequest(params);
      // console.log("siteSettingEditRes", siteSettingEditRes);
      if (siteSettingEditRes.status) {
        const response = siteSettingEditRes.data;
        setSiteSettingEdit(response.adminPermissions.siteSetting.Edit);
        setAdminType(response.admin_type);
      } else {
        toast(siteSettingEditRes.message);
        //console.log(siteSettingEditRes.message); 

      }
    } catch (error) {
      console.log("err", error);
      // toast.error(error);
    }
  };
  useEffect(() => {
    SitesettingRes();
  }, []);

  useEffect(() => {
    fetchSiteSettings();
  }, []);

  const fetchSiteSettings = async () => {
    try {
      let params = {
        url: "get-site-setting",
        method: "GET",
      };

      const res = await makeApiRequest(params);

      // console.log("Site settings fetched:", res);

      if (res.status && res.data) {
        const data = res.data;

        // Set fields from backend
        setEmailContent(data.emailContent || "");
        setExpireTime(data.expireTime || "");
        setCopyright(data.copyright || "");
        setEmailSubject(data.emailSubject || "");
        setResendOTPExpireTime(data.resendOTPexpireTime || "");
        setLogoPosition(data.logoPosition || "center");
        // setLastLine(data.lastLine || "");


        // Show preview image if logo exists (assume backend gives full URL)
        if (data.logo) {
          setPreviewImage(data.logo); // should be a URL
        }
      }
    } catch (err) {
      console.log("Failed to fetch site settings");
    }
  };

  const handleImageChange = (e) => {
    const file = e.target.files[0];

    setImageFile(null);
    setPreviewImage(null);
    setIsImageValid(false);

    if (!file) return;

    const allowedTypes = ["image/jpeg", "image/jpg", "image/png"];
    const maxSize = 1 * 1024 * 1024;

    if (!allowedTypes.includes(file.type)) {
      toast.error("Only JPG, JPEG, or PNG files are allowed.");
      return;
    }

    if (file.size > maxSize) {
      toast.error("File size should not exceed 1MB.");
      return;
    }

    const reader = new FileReader();
    reader.onload = (event) => {
      const img = new Image();
      img.onload = () => {
        const { width, height } = img;
        if (width < 100 || height < 100 || width > 1000 || height > 1000) {
          toast.error(
            "Image resolution must be between 100x100 and 1000x1000."
          );
          return;
        }

        // ✅ All validations passed
        setImageFile(file);
        setPreviewImage(event.target.result);
        setIsImageValid(true);
      };
      img.onerror = () => {
        toast.error("Invalid image file.");
      };

      img.src = event.target.result;
    };
    reader.readAsDataURL(file);
  };

  const submitSiteSetting = async (e) => {
    e.preventDefault();
    if (siteSettingEdit == 0 && adminType == "SubAdmin") {
      toast.warning(
        "Access Denied: You are not allowed to Edit the  siteSetting details."
      );
      return;
    } else if (siteSettingEdit == 1 || adminType == "SuperAdmin") {
      if (!emailSubject || !emailContent || !expireTime || !copyright) {
        toast.error("All required fields must be filled.");
        return;
      }

      if (isImageValid == false || previewImage == null) {
        toast.error("Please upload a valid image before submitting.");
        return;
      }

      const formData = new FormData();
      if (imageFile) formData.append("logo", imageFile);
      if (emailSubject) formData.append("emailSubject", emailSubject);
      if (emailContent) formData.append("emailContent", emailContent);
      if (expireTime) formData.append("expireTime", expireTime);
      if (copyright) formData.append("copyright", copyright);
      // if (lastLine) formData.append("lastLine", lastLine);
      if (logoPosition) formData.append("logoPosition", logoPosition);
      if (resendOTPexpireTime) formData.append("resendOTPexpireTime", resendOTPexpireTime);

      const address = await axios.get("https://api.ipify.org/?format=json");
      const lastloginIpAddress = address.data.ip;
      if (lastloginIpAddress) formData.append("ip", lastloginIpAddress);

      setLoading(true);

      try {
        const params = {
          url: "site-setting",
          method: "POST",
          data: formData,
          header: "image",
        };

        const res = await makeApiRequest(params);
        if (res.status) {
          toast.success(res.message || "Site settings updated successfully");
        } else {
          toast.error(res.message || "Failed to update settings");
        }
      } catch (err) {
        console.log("Error updating site settings", err);
      } finally {
        setLoading(false);
      }
    }
  };
  // rendrenderPreviewTemplateer code .......
  const renderPreviewTemplate = () => {
    return (
      <main
        style={{
          maxWidth: "600px",
          margin: "0px auto",
          padding: "20px",
          border: "0px solid #bc9018",
          fontFamily: "sans-serif",
        }}
      >
        <h3
          style={{
            fontSize: "18px",
            fontWeight: "bold",
            marginBottom: "20px",
          }}
        >
          Subject: {emailSubject}
        </h3>
        {previewImage && (
          <div
            style={{
              textAlign:
                logoPosition === "left"
                  ? "left"
                  : logoPosition === "right"
                    ? "right"
                    : "center",
              marginBottom: "20px",
            }}
          >
            <img src={previewImage} alt="logo" style={{ width: "150px" }} />
          </div>
        )}

        {/* Email Body */}
        <p style={{ fontSize: "14px", marginBottom: "10px" }}>
          Dear <strong>User</strong>,
        </p>

        <p style={{ fontSize: "14px", marginBottom: "10px" }}>
          Thank you for registering with <strong>NVXO</strong>.
        </p>

        <p style={{ fontSize: "14px", marginBottom: "5px" }}>
          To complete your email verification, please use the One-Time Password
          (OTP) provided below:
        </p>


        {/* OTP */}
        <div
          style={{
            // textAlign: "center",
            fontSize: "20px",
            fontWeight: "bold",
            letterSpacing: "3px",
            marginBottom: "5px",
            color: "#58f9b0",
          }}
        >
          123456
        </div>

        {/* Expiry */}
        <p style={{ fontSize: "14px", marginBottom: "15px" }}>
          This OTP is valid for the next{" "}
          <strong>{expireTime || "10"} minutes</strong>. For security reasons,
          please do not share this code with anyone.
        </p>

        {/* Signature */}
        <p style={{ fontSize: "14px", marginTop: "25px" }}>
          Sincerely,
          <br />
          <strong>{"NVXO Team"}</strong>
        </p>

        {/* Footer */}
        <footer
          style={{
            marginTop: "30px",
            fontSize: "12px",
            textAlign: "center",
            color: "#777",
            backgroundColor: "#f6f6f6",
            padding: "15px",
          }}
          dangerouslySetInnerHTML={{ __html: copyright }}
        />
      </main>
    );
  };

  return (
    <>
      <ToastContainer />
      <div className="container-fluid pb-5">
        <div className="text-dark">
          <div className="row">
            <div className="col-lg-12">
              <div className="custom-nav-userlist-1">
                <h3 className="component-user ms-lg-0 mt-4">Site Setting</h3>

                <ul className="nav nav-pills">
                  <li className="nav-item">
                    <button
                      className="nav-link active"
                      data-bs-toggle="pill"
                      data-bs-target="#copyright"
                    >
                      Email Template
                    </button>
                  </li>
                </ul>

                <div className="tab-content">
                  {/* Copyright */}
                  <div className="tab-pane fade show active" id="copyright">
                    <div className="row">
                      <div className="col-lg-6">
                        <h5 className="component-user ms-lg-0 mt-4">
                          User Registration OTP Mail
                        </h5>
                        <div className="setting-tabs">
                          <form onSubmit={submitSiteSetting}>
                            <div className="mb-3">
                              <label className="form-label">Upload Logo</label>
                              <input
                                type="file"
                                className="form-control"
                                accept="image/*"
                                onChange={handleImageChange}
                                disabled={
                                  siteSettingEdit == 0 &&
                                  adminType == "SubAdmin"
                                }
                              />
                              <small className="text-muted d-block mt-2">
                                Allowed formats: JPG, JPEG, PNG. Max size: 1MB.{" "}
                                <br />
                                <strong>
                                  Image resolution must be between 100x100 and
                                  1000x1000.
                                </strong>
                              </small>

                              <div className="mt-3">
                                <label className="form-label">Logo Placement</label>
                                <select
                                  className="form-select"
                                  value={logoPosition}
                                  onChange={(e) => setLogoPosition(e.target.value)}
                                  disabled={siteSettingEdit == 0 && adminType == "SubAdmin"}
                                >
                                  <option value="left">Left</option>
                                  <option value="center">Center</option>
                                  <option value="right">Right</option>
                                </select>
                              </div>

                              {previewImage && (
                                <div className="mt-4">
                                  <p className="mb-1 form-label">Preview:</p>
                                  <img
                                    src={previewImage}
                                    alt="Preview"
                                    className="img-thumbnail"
                                    style={{ maxWidth: "200px" }}
                                  />
                                </div>
                              )}
                            </div>

                            <div className="mb-3">
                              <label className="form-label">
                                Email Subject
                              </label>
                              <input
                                type="text"
                                className="form-control"
                                value={emailSubject}
                                onChange={(e) =>
                                  setEmailSubject(e.target.value)
                                }
                                disabled={
                                  siteSettingEdit == 0 &&
                                  adminType == "SubAdmin"
                                }
                                placeholder="Enter email subject"
                              />
                            </div>

                            <div className="mb-3">
                              <label className="form-label">
                                Email Content
                              </label>
                              <textarea
                                className="form-control"
                                rows="3"
                                value={emailContent}
                                onChange={(e) =>
                                  setEmailContent(e.target.value)
                                }
                                disabled={
                                  siteSettingEdit == 0 &&
                                  adminType == "SubAdmin"
                                }
                                placeholder="Email content"
                              />
                            </div>

                            <div className="mb-3">
                              <label className="form-label">
                                OTP Expire Time (in minutes)
                              </label>
                              <input
                                type="text"
                                inputMode="numeric"
                                pattern="[0-9]*"
                                className="form-control"
                                value={expireTime}
                                onChange={(e) => {
                                  const val = e.target.value;
                                  if (/^\d*$/.test(val)) setExpireTime(val);
                                }}
                                disabled={
                                  siteSettingEdit == 0 &&
                                  adminType == "SubAdmin"
                                }
                                placeholder="e.g. 5"
                              />
                            </div>

                            <div className="mb-3">
                              <label className="form-label">
                                Resend OTP Expire Time (in minutes)
                              </label>
                              <input
                                type="text"
                                inputMode="numeric"
                                pattern="[0-9]*"
                                className="form-control"
                                value={resendOTPexpireTime}
                                onChange={(e) => {
                                  const val = e.target.value;
                                  if (/^\d*$/.test(val))
                                    setResendOTPExpireTime(val);
                                }}
                                disabled={
                                  siteSettingEdit == 0 &&
                                  adminType == "SubAdmin"
                                }
                                placeholder="e.g. 5"
                              />
                            </div>

                            {/* <div className="mb-3">
                              <label className="form-label">Last Line</label>
                              <input
                                type="text"
                                className="form-control"
                                value={lastLine}
                                onChange={(e) => setLastLine(e.target.value)}
                                disabled={
                                  siteSettingEdit == 0 &&
                                  adminType == "SubAdmin"
                                }
                                placeholder="Enter Content"
                              />
                            </div> */}

                            <div className="mb-3">
                              <label className="form-label">Copyright</label>
                              <input
                                type="text"
                                className="form-control"
                                value={copyright}
                                onChange={(e) => setCopyright(e.target.value)}
                                disabled={
                                  siteSettingEdit == 0 &&
                                  adminType == "SubAdmin"
                                }
                                placeholder="2025 @ NVXO"
                              />
                            </div>

                            <div className="mt-4 d-flex justify-content-between">
                              <button
                                type="submit"
                                className="custom-nav-button-1 active"
                                disabled={loading}
                              >
                                {loading ? "Submitting..." : "Submit"}
                              </button>
                              <button
                                type="button"
                                className="custom-nav-button-2 fs-6 py-1"
                                onClick={() => {
                                  if (
                                    siteSettingEdit == 0 &&
                                    adminType == "SubAdmin"
                                  ) {
                                    toast.warning(
                                      "Access Denied: You do not have permission to view the preview page"
                                    );
                                  } else {
                                    setPreviewOpen(true);
                                  }
                                }}
                              >
                                Preview <MdOutlineRemoveRedEye />
                              </button>
                            </div>
                          </form>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>

        <Modal
          show={previewOpen}
          onHide={() => setPreviewOpen(false)}
          size="lg"
          centered
        >
          <Modal.Header closeButton className="border-0"></Modal.Header>
          <Modal.Body>{renderPreviewTemplate()}</Modal.Body>
        </Modal>
      </div>
    </>
  );
}

export default Sitesetting;
